def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)

    other_counts = {v: n for v, n in counts.items() if v != background}
    if not other_counts:
        return [row[:] for row in grid]
    bar_color = max(other_counts, key=other_counts.get)
    markers = [
        (r, c, grid[r][c])
        for r in range(h) for c in range(w)
        if grid[r][c] not in (background, bar_color)
    ]
    if not markers:
        return [row[:] for row in grid]

    # Find contiguous runs of the bar color on each edge.
    edges = {}
    for side in ("top", "bottom", "left", "right"):
        if side in ("top", "bottom"):
            r = 0 if side == "top" else h - 1
            seq = [grid[r][c] for c in range(w)]
        else:
            c = 0 if side == "left" else w - 1
            seq = [grid[r][c] for r in range(h)]

        runs = []
        i = 0
        while i < len(seq):
            if seq[i] != bar_color:
                i += 1
                continue
            start = i
            while i < len(seq) and seq[i] == bar_color:
                i += 1
            if i - start >= 2:
                runs.append((start, i - 1))
        edges[side] = runs

    def marker_count(orientation, run):
        a, b = run
        if orientation == "horizontal":
            return sum(a <= c <= b for r, c, _ in markers)
        return sum(a <= r <= b for r, c, _ in markers)

    candidates = []
    for orientation, side1, side2 in (
        ("horizontal", "top", "bottom"),
        ("vertical", "left", "right"),
    ):
