            for run2 in edges[side2]:
                if run1[1] - run1[0] != run2[1] - run2[0]:
                    continue
                n1 = marker_count(orientation, run1)
                n2 = marker_count(orientation, run2)
                candidates.append((max(n1, n2), run1[1] - run1[0] + 1,
                                   orientation, side1, run1, side2, run2, n1, n2))

    if not candidates:
        return [row[:] for row in grid]

    _, _, orientation, side1, run1, side2, run2, n1, n2 = max(
        candidates, key=lambda x: (x[0], x[1])
    )
    if n1 >= n2:
        source_side, source_run = side1, run1
        target_side, target_run = side2, run2
    else:
        source_side, source_run = side2, run2
        target_side, target_run = side1, run1

    out = [row[:] for row in grid]
    s0, s1 = source_run
    t0, _ = target_run
    active_offsets = set()

    for r, c, color in markers:
