        if not (s0 <= along <= s1):
            continue
        active_offsets.add(along - s0)

        # Extend the marker's ray back to its source edge.
        if source_side == "top":
            for rr in range(1, r):
                out[rr][c] = color
        elif source_side == "bottom":
            for rr in range(r + 1, h - 1):
                out[rr][c] = color
        elif source_side == "left":
            for cc in range(1, c):
                out[r][cc] = color
        else:  # right
            for cc in range(c + 1, w - 1):
                out[r][cc] = color
        out[r][c] = 4

    # Copy the occupied positions to the paired edge and extend their rays inward.
    for offset in active_offsets:
        along = t0 + offset
        if target_side == "top":
            for rr in range(1, h):
                if grid[rr][along] != bar_color and out[rr][along] != 4:
                    out[rr][along] = markers[0][2]
        elif target_side == "bottom":
            for rr in range(h - 2, -1, -1):
                if grid[rr][along] != bar_color and out[rr][along] != 4:
                    out[rr][along] = markers[0][2]
        elif target_side == "left":
            for cc in range(1, w):
